import java.util.*;import java.util.concurrent.*;
class Station extends Thread{int id;Station(int n){id=n;}public void run(){try{Thread.sleep(20+id*13);}catch(InterruptedException e){interrupt();}System.out.println(getName()+" scanned "+(id*25));}}
class StationJob implements Runnable{int id;StationJob(int n){id=n;}public void run(){try{Thread.sleep(15+id*11);}catch(InterruptedException e){Thread.currentThread().interrupt();}System.out.println(Thread.currentThread().getName()+" scanned "+(id*25));}}
public class ScannerStations{public static void main(String[]x)throws Exception{Thread[]a=new Thread[4];for(int i=0;i<4;i++){a[i]=new Station(i+1);a[i].start();}for(Thread t:a)t.join();System.out.println("Thread subclass stations complete");Thread[]b=new Thread[4];for(int i=0;i<4;i++){b[i]=new Thread(new StationJob(i+1),"Runnable-"+(i+1));b[i].start();}for(Thread t:b)t.join();System.out.println("Runnable stations complete; any alive="+Arrays.stream(b).anyMatch(Thread::isAlive));System.out.println("Direct run() uses "+Thread.currentThread().getName());new StationJob(9).run();for(int r=1;r<=10;r++){List<Integer>order=Collections.synchronizedList(new ArrayList<>());CountDownLatch done=new CountDownLatch(4);for(int i=1;i<=4;i++){final int id=i;new Thread(()->{try{Thread.sleep(ThreadLocalRandom.current().nextInt(5,40));}catch(InterruptedException e){Thread.currentThread().interrupt();}order.add(id);done.countDown();}).start();}done.await();System.out.println("Run "+r+" finish order "+order);}}}